def minimumSwap(s1: str, s2: str) -> int:
    # Count mismatches
    mismatch_x = 0
    mismatch_y = 0

    for c1, c2 in zip(s1, s2):
        if c1 != c2:
            if c1 == 'x':
                mismatch_x += 1
            else:
                mismatch_y += 1

    # If the total number of mismatches is odd, it's impossible to make them equal
    if (mismatch_x + mismatch_y) % 2 != 0:
        return -1

    # Calculate the minimum number of swaps
    swaps = mismatch_x // 2 + mismatch_y // 2
    if mismatch_x % 2 != 0:
        swaps += 2

    return swaps
